insert into public.topics (slug, title, description, position)
values ($g0$verbals$g0$, $g1$Неособові форми дієслова (Verbals)$g1$, $g2$Неособові форми дієслова: форми й функції інфінітива, інфінітив без to, складний додаток і складний підмет, герундій, вибір між інфінітивом і -ing, too/enough, дієприкметники.$g2$, 7)
on conflict (slug) do update set title = excluded.title,
