insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g3$th_hero$g3$, $g4$Неособові форми дієслова$g4$, $g5$elementary$g5$, $g6$hero$g6$, $g7${"title":"Verbals","chips":["Англійська граматика","Інфінітив · герундій · дієприкметник"],"lead":"Дієслівні форми, які <b>не змінюються за особами</b> і самі не бувають присудком. Головне питання теми — <b>яку форму вимагає слово перед ними</b>: дієслово, прикметник чи прийменник.","diagramTitle":"Три неособові форми","diagram":[{"role":"інфінітив","label":"(to) do","tone":"opinion"},{"role":"герундій — як іменник","label":"doing","tone":"colour"},{"role":"дієприкметник — як прикметник","label":"doing · done","tone":"age"}],"diagramJoin":"·","diagramNote":"want <b>to go</b> · enjoy <b>reading</b> · a <b>broken</b> window"}$g7$::jsonb, null, 0
from public.topics where slug = $g8$verbals$g8$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g9$th_1$g9$, $g10$Неособові форми дієслова: загальна карта$g10$, $g11$elementary$g11$, $g12$cases$g12$, $g13${"step":"Карта","kicker":"Базове розуміння","lead":"Неособових форм три. Кожна грає роль іншої частини мови: інфінітив і герундій — як іменник, дієприкметник — як прикметник чи прислівник.","cards":[{"icon":"→","title":"Infinitive · (to) do","text":"Початкова форма дієслова, зазвичай із часткою to.","example":"I want <b>to go</b> home.","examplePlain":"I want to go home."},{"icon":"◆","title":"Gerund · doing","text":"Дієслово з -ing, яке працює як іменник: підмет, додаток, після прийменника.","example":"<b>Swimming</b> is good for you. / I enjoy <b>reading</b>.","examplePlain":"Swimming is good for you. I enjoy reading."},{"icon":"◐","title":"Participle · doing / done","text":"Дієприкметник: описує іменник, як прикметник.","example":"a <b>crying</b> baby / a <b>broken</b> window","examplePlain":"a crying baby, a broken window"}],"axis":{"title":"Форму вирішує слово перед нею","points":[{"label":"дієслово","text":"want → <b>to go</b> · enjoy → <b>going</b>"},{"label":"прикметник","text":"easy → <b>to please</b>"},{"label":"прийменник","text":"of / for / in → <b>doing</b>"}],"note":"Після будь-якого прийменника — тільки -ing."}}$g13$::jsonb, null, 1
from public.topics where slug = $g14$verbals$g14$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g15$th_2$g15$, $g16$Форми інфінітива: час і стан$g16$, $g17$intermediate$g17$, $g18$formula$g18$, $g19${"step":"Форми інфінітива","kicker":"Відносний час","lead":"Інфінітив має чотири форми в активному стані й дві в пасивному. Його «час» завжди <b>відносний</b> — щодо дії дієслова-присудка.","tiles":[{"role":"одночасно / потім","label":"to write","tone":"opinion"},{"role":"у процесі","label":"to be writing","tone":"size"},{"role":"раніше","label":"to have written","tone":"colour"},{"role":"тривало до моменту","label":"to have been writing","tone":"origin"}],"examples":[{"text":"I was glad <b>to see</b> Mr Paul.","plain":"I was glad to see Mr Paul.","note":"Simple"},{"text":"He pretended <b>to be sleeping</b>.","plain":"He pretended to be sleeping.","note":"Continuous"},{"text":"I was sorry <b>to have said</b> it.","plain":"I was sorry to have said it.","note":"Perfect"},{"text":"He seems <b>to have been reading</b> since morning.","plain":"He seems to have been reading since morning.","note":"Perfect Continuous"},{"text":"It is wonderful to love and <b>to be loved</b>.","plain":"It is wonderful to love and to be loved.","note":"Passive"}],"note":"Заперечення — <b>not + to-infinitive</b>: <i>She asked me <b>not to forget</b>.</i>","tabs":[{"title":"Таблиця форм","html":"<div class=\"overflow-x-auto mb-3\"><table class=\"w-full text-body-sm border-collapse\">\n  <thead><tr><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\"></th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Active</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Passive</th></tr></thead>\n  <tbody><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">Simple</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">to write</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">to be written</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">Continuous</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">to be writing</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">—</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">Perfect</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">to have written</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">to have been written</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">Perfect Continuous</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">to have been writing</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">—</td></tr></tbody>\n</table></div><p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">Perfect після модального — висновок про минуле: <i>He must <b>have forgotten</b> about it.</i></p>"}]}$g19$::jsonb, null, 2
