insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g21$th_3$g21$, $g22$Інфінітив без to (bare infinitive)$g22$, $g23$intermediate$g23$, $g24$formula$g24$, $g25${"step":"Без to","kicker":"Коли частка зникає","lead":"Зазвичай інфінітив стоїть із часткою <b>to</b>, але після певних слів її немає.","tiles":[{"role":"модальні","label":"must do","tone":"opinion"},{"role":"make · let · have","label":"make sb do","tone":"colour"},{"role":"see · hear · feel","label":"see sb do","tone":"size"},{"role":"had better · would rather","label":"'d better do","tone":"age"}],"legend":[{"tone":"neutral","label":"а також: why (not) · cannot but · but / except / rather than"}],"examples":[{"text":"You <b>must consult</b> the doctor.","plain":"You must consult the doctor.","note":"АЛЕ ought to help"},{"text":"What <b>makes</b> you <b>think</b> so? / <b>Let</b> me <b>know</b>.","plain":"What makes you think so? / Let me know.","note":"make / let"},{"text":"She <b>heard</b> him <b>enter</b> the room.","plain":"She heard him enter the room.","note":"сприйняття"},{"text":"<b>Why not come</b> and talk to her yourself?","plain":"Why not come and talk to her yourself?","note":"why not"},{"text":"I'll do anything <b>but work</b>.","plain":"I'll do anything but work.","note":"but = крім"}],"note":"<b>У пасиві to повертається:</b> <i>He <b>was made to apologise</b>. / He <b>was heard to mention</b> your name.</i>","tabs":[{"title":"help і dare","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">Після <b>help</b> — з to або без:</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">Can you help me <b>(to) fill</b> in this form?</div><p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\"><b>dare</b> у запереченнях і питаннях часто без to:</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">How <b>dare</b> you <b>call</b> me a liar?</div>"},{"title":"and / or і повтор","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">Друге дієслово після <i>and / or</i> може бути без to, а щоб не повторювати дієслово, лишаємо тільки to:</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">He agreed <b>to come and help</b> us.<br>'Shall we go?' 'I'd like <b>to</b>.'</div>"},{"title":"have sb do","html":"<div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\"><b>Have</b> the driver <b>bring</b> the car.<br>You<b>'d better go</b>. / I<b>'d rather stay</b>. / I <b>can't but think</b> about it.</div>"}]}$g25$::jsonb, null, 3
from public.topics where slug = $g26$verbals$g26$
