insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g27$th_4$g27$, $g28$Функції інфінітива: підмет, предикатив, мета$g28$, $g29$intermediate$g29$, $g30$cases$g30$, $g31${"step":"Функції","kicker":"Член речення","lead":"Інфінітив може бути майже будь-яким членом речення. Найчастіша роль — <b>мета</b>: «для того, щоб».","cards":[{"icon":"1","title":"Підмет","text":"Частіше — з формальним it на початку.","example":"<b>It</b> is important <b>to explain</b> everything.","examplePlain":"It is important to explain everything."},{"icon":"=","title":"Предикатив","text":"Іменна частина присудка після be.","example":"Her first action <b>was to visit</b> the studio.","examplePlain":"Her first action was to visit the studio."},{"icon":"◇","title":"Додаток","text":"Після дієслова.","example":"I hope <b>to see</b> you soon.","examplePlain":"I hope to see you soon."},{"icon":"◎","title":"Мета","text":"(in order / so as) + to-inf. НЕ for to. Заперечна мета — in order not to / so as not to.","example":"He took off his boots <b>so as not to make</b> any noise.","examplePlain":"He took off his boots so as not to make any noise."},{"icon":"☺","title":"for + sb + to-inf","text":"Коли дію виконує інша особа.","example":"<b>For Bob to retire</b> so young was unexpected.","examplePlain":"For Bob to retire so young was unexpected."},{"icon":"!","title":"only to","text":"Несподіваний, часто прикрий результат.","example":"We rushed to the station <b>only to arrive</b> as the train was leaving.","examplePlain":"We rushed to the station only to arrive as the train was leaving."}]}$g31$::jsonb, null, 4
