insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g33$th_6$g33$, $g34$Too / enough + інфінітив$g34$, $g35$elementary$g35$, $g36$formula$g36$, $g37${"step":"Too / enough","kicker":"Занадто чи достатньо","lead":"<b>Too</b> = «занадто» (тому неможливо). <b>Enough</b> = «достатньо» (тому можливо). Порядок слів у них протилежний.","tiles":[{"role":"занадто","label":"too + adj + to-inf","tone":"origin"},{"role":"достатньо","label":"adj + enough + to-inf","tone":"age"},{"role":"з іменником","label":"enough + noun + to-inf","tone":"size"}],"examples":[{"text":"The tea is <b>too hot to drink</b>.","plain":"The tea is too hot to drink.","note":"занадто"},{"text":"This box is <b>too heavy for me to lift</b>.","plain":"This box is too heavy for me to lift.","note":"for + sb"},{"text":"He is <b>strong enough to lift</b> it.","plain":"He is strong enough to lift it.","note":"НЕ enough strong"},{"text":"We've got <b>enough time to go</b> shopping.","plain":"We've got enough time to go shopping.","note":"enough перед іменником"},{"text":"He <b>didn't run fast enough to win</b>.","plain":"He didn't run fast enough to win.","note":"not … enough"}],"note":"<b>Типова помилка:</b> <s>too hot to drink it</s> — додаток повторювати не треба."}$g37$::jsonb, null, 5
