insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g39$th_8$g39$, $g40$Складний додаток (Complex Object): I want you to go$g40$, $g41$intermediate$g41$, $g42$formula$g42$, $g43${"step":"Complex Object","kicker":"Хочу, щоб ти…","lead":"Українське «я хочу, <b>щоб ти</b> пішов» англійською — один простий зворот: <b>want + додаток + to-inf</b>. Підрядного речення з that тут бути не може.","tiles":[{"role":"підмет","label":"I","tone":"neutral"},{"role":"дієслово","label":"want","tone":"opinion"},{"role":"додаток","label":"you / him / them","tone":"colour"},{"role":"інфінітив","label":"to go","tone":"noun"}],"examples":[{"text":"I want <b>you to stop</b> worrying.","plain":"I want you to stop worrying.","note":"НЕ I want that you stop"},{"text":"We expect <b>them to arrive</b> soon.","plain":"We expect them to arrive soon.","note":"думка"},{"text":"Tell me what you would like <b>me to do</b>.","plain":"Tell me what you would like me to do.","note":"почуття"},{"text":"The colonel ordered <b>his men to attack</b>.","plain":"The colonel ordered his men to attack.","note":"наказ"},{"text":"…ordered <b>the cases to be loaded</b>.","plain":"…ordered the cases to be loaded.","note":"пасивний інфінітив"}],"note":"Якщо виконавець = підмет, додатка немає: <i>She wants <b>to be invited</b>.</i> (хоче, щоб її запросили). Для однієї особи — зворотний займенник: <i>He considers <b>himself to be</b> right.</i>","tabs":[{"title":"Групи дієслів","html":"<div class=\"overflow-x-auto mb-3\"><table class=\"w-full text-body-sm border-collapse\">\n  <thead><tr><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\"></th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">дієслова</th></tr></thead>\n  <tbody><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">бажання</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">want, wish, would like, mean, intend</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">думка</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">know, think, consider, believe, find, expect, suppose</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">заява</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">pronounce, declare, report</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">почуття</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">like, love, hate, cannot bear</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">наказ, дозвіл</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">order, allow, ask, encourage, forbid</td></tr></tbody>\n</table></div>"},{"title":"to be","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">Після дієслів думки й заяви часто стоїть <b>to be</b>:</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">I find <b>him (to be)</b> a very clever man.<br>The doctor pronounced <b>the wound to be</b> a slight one.</div>"}]}$g43$::jsonb, null, 6
