insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g45$th_9$g45$, $g46$Складний додаток після see, hear, watch, feel$g46$, $g47$advanced$g47$, $g48$formula$g48$, $g49${"step":"See sb do / doing","kicker":"Дієслова сприйняття","lead":"Після дієслів сприйняття інфінітив стоїть <b>без to</b>. Якщо важливий сам процес — вживаємо <b>-ing</b>.","tiles":[{"role":"бачив усю дію","label":"see sb do","tone":"opinion"},{"role":"застав процес","label":"see sb doing","tone":"colour"},{"role":"пасив","label":"see sth done","tone":"size"}],"examples":[{"text":"I saw him <b>enter</b> the shop.","plain":"I saw him enter the shop.","note":"увійшов, бачив від початку до кінця"},{"text":"I saw him <b>entering</b> the shop.","plain":"I saw him entering the shop.","note":"саме входив"},{"text":"I felt <b>the blood rush</b> into my cheeks.","plain":"I felt the blood rush into my cheeks.","note":"уся дія"},{"text":"He watched <b>his camera being repaired</b>.","plain":"He watched his camera being repaired.","note":"процес у пасиві"},{"text":"I saw <b>the fire</b> slowly <b>conquered</b>.","plain":"I saw the fire slowly conquered.","note":"Participle II"}],"note":"У пасиві to повертається: <i>He <b>was seen to leave</b>.</i>","tabs":[{"title":"Підрядне речення","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\"><b>see</b> = розуміти, <b>hear</b> = дізнатися, а також see / notice + be → підрядне речення:</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">I <b>saw that</b> she didn't realize the danger.<br>I <b>heard that</b> he had left.<br>I saw <b>that he was</b> disappointed.</div>"}]}$g49$::jsonb, null, 7
