insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g51$th_10$g51$, $g52$Складний підмет (Complex Subject): He is said to be…$g52$, $g53$advanced$g53$, $g54$formula$g54$, $g55${"step":"Complex Subject","kicker":"Кажуть, що він…","lead":"Українське «<b>кажуть, що</b> він…», «<b>здається</b>, він…», «він, <b>напевно</b>, …» англійською будується так, що людина стає підметом.","tiles":[{"role":"пасив: кажуть, вважають","label":"be said · be known","tone":"opinion"},{"role":"актив: здається, виявилось","label":"seem · appear · happen","tone":"colour"},{"role":"напевно","label":"be likely · be sure","tone":"age"}],"legend":[{"tone":"opinion","label":"be said, be reported, be known, be believed, be thought, be expected, be supposed, be considered"},{"tone":"colour","label":"seem, appear, happen, turn out, prove"},{"tone":"age","label":"be likely, be sure, be certain, be bound"}],"examples":[{"text":"He <b>is said to be</b> a good singer.","plain":"He is said to be a good singer.","note":"кажуть, що…"},{"text":"Roman <b>seems to know</b> English well.","plain":"Roman seems to know English well.","note":"здається…"},{"text":"I <b>happened to see</b> him.","plain":"I happened to see him.","note":"випадково"},{"text":"He <b>is sure to come</b>.","plain":"He is sure to come.","note":"обов'язково прийде"},{"text":"He is said <b>to have spent</b> his youth in Paris.","plain":"He is said to have spent his youth in Paris.","note":"Perfect — раніше"}],"note":"Перетворення: <i>It is reported that the delegation has left.</i> → <i>The delegation <b>is reported to have left</b>.</i>","tabs":[{"title":"Форма показує час","html":"<div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">They seem <b>to be quarrelling</b>. — зараз<br>He seems <b>to have been reading</b> since morning. — тривало досі</div><p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">Також: <i>They <b>were advised to come</b> in time. / He <b>was ordered not to go</b> there.</i></p>"}]}$g55$::jsonb, null, 8
