insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g57$th_11$g57$, $g58$Герундій: форми та функції$g58$, $g59$intermediate$g59$, $g60$formula$g60$, $g61${"step":"Герундій","kicker":"-ing як іменник","lead":"Герундій — дієслово з <b>-ing</b>, яке працює як <b>іменник</b>: може бути підметом, додатком, стояти після прийменника. Українською часто перекладаємо іменником або інфінітивом.","tiles":[{"role":"одночасно / потім","label":"doing","tone":"opinion"},{"role":"раніше","label":"having done","tone":"colour"},{"role":"пасив","label":"being done","tone":"size"},{"role":"пасив, раніше","label":"having been done","tone":"origin"}],"examples":[{"text":"Are you thinking of <b>getting</b> a new phone?","plain":"Are you thinking of getting a new phone?","note":"Simple"},{"text":"He apologises for <b>having been</b> late.","plain":"He apologises for having been late.","note":"Perfect"},{"text":"She knows of <b>being praised</b>.","plain":"She knows of being praised.","note":"Passive: знає, що її хвалять"},{"text":"<b>Rollerskating</b> is exciting.","plain":"Rollerskating is exciting.","note":"підмет"},{"text":"<b>Before going</b> to work, she cooks breakfast.","plain":"Before going to work, she cooks breakfast.","note":"обставина"}],"tabs":[{"title":"Герундіальний комплекс","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">Присвійний займенник або іменник + gerund: дію виконує хтось інший.</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">I don't remember <b>her taking</b> part.<br>I don't approve of <b>his wasting</b> time.</div><p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">У розмові замість <i>his</i> часто <i>him</i>: <i>him wasting</i>.</p>"},{"title":"Означення","html":"<div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">her idea <b>of having</b> a party<br><b>By acquiring</b> skills…</div>"}]}$g61$::jsonb, null, 9
