insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g63$th_12$g63$, $g64$Дієслова та вирази, після яких тільки -ing$g64$, $g65$intermediate$g65$, $g66$formula$g66$, $g67${"step":"Тільки -ing","kicker":"Вивчити списком","lead":"Цю групу треба запам'ятати: після цих слів інфінітив неможливий.","tiles":[{"role":"дієслово зі списку","label":"enjoy · avoid · suggest…","tone":"opinion"},{"role":"тільки","label":"V-ing","tone":"colour"}],"examples":[{"text":"Why do you systematically <b>avoid meeting</b> me?","plain":"Why do you systematically avoid meeting me?","note":"avoid"},{"text":"Would you <b>mind turning</b> the radio down?","plain":"Would you mind turning the radio down?","note":"mind"},{"text":"I <b>suggest calling</b> the cinema.","plain":"I suggest calling the cinema.","note":"НЕ suggest to call"},{"text":"She <b>spent</b> a long time <b>talking</b> on the phone.","plain":"She spent a long time talking on the phone.","note":"spend time"},{"text":"I <b>look forward to seeing</b> you.","plain":"I look forward to seeing you.","note":"to — прийменник"}],"note":"Порівняйте: <i>I <b>used to work</b> at night.</i> (раніше працював) — <i>I'm <b>used to working</b> at night.</i> (звик).","tabs":[{"title":"Дієслова","html":"<div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">enjoy · avoid · mind · suggest · postpone / put off · consider · deny · finish · keep · mention · miss · practise · risk · can't stand · can't help · spend time</div>"},{"title":"Вирази","html":"<div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">it's no use · there's no point (in) · it's (not) worth · have difficulty (in)</div><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">It's <b>no use trying</b>.<br>This restaurant is <b>worth visiting</b>.</div>"},{"title":"to як прийменник","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">У цих виразах <b>to</b> — прийменник, тому далі -ing:</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">look forward to · be / get used to · be accustomed to · object to · in addition to</div>"}]}$g67$::jsonb, null, 10
