insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g69$th_13$g69$, $g70$Прийменник + герундій$g70$, $g71$advanced$g71$, $g72$cases$g72$, $g73${"step":"Прийменник + -ing","kicker":"Який прийменник","lead":"Після <b>будь-якого прийменника</b> дієслово стоїть у формі -ing. Складність — запам'ятати, який прийменник вимагає те чи інше слово: verb / adjective / noun + preposition + (my / him…) + V-ing.","cards":[{"icon":"◆","title":"of","text":"accuse sb of, suspect sb of, be capable of, be guilty of, dream of, think of, approve of, be in charge of, take advantage of, be afraid of, be tired of"},{"icon":"▣","title":"in","text":"be interested in, succeed in, be involved in, be experienced in, there's no sense in, (have) difficulty in"},{"icon":"✓","title":"for","text":"blame sb for, apologise for, be sorry for, (have) a reason / an excuse for, be responsible for, thank sb for","example":"The manager blamed Silvia <b>for losing</b> the deal.","examplePlain":"The manager blamed Silvia for losing the deal."},{"icon":"⇥","title":"on · from","text":"insist on, congratulate sb on, rely on · prevent / stop sb from"},{"icon":"…","title":"about · by","text":"complain about, be excited about · by doing — у такий спосіб","example":"Fiona's husband complains <b>about her spending</b> money.","examplePlain":"Fiona's husband complains about her spending money."},{"icon":"↺","title":"Пасивний герундій","text":"Коли дію виконують над підметом.","example":"Sam is not accustomed to <b>being treated</b> disrespectfully.","examplePlain":"Sam is not accustomed to being treated disrespectfully."}]}$g73$::jsonb, null, 11
