insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g75$th_14$g75$, $g76$Інфінітив або -ing без зміни значення$g76$, $g77$intermediate$g77$, $g78$formula$g78$, $g79${"step":"To do = doing","kicker":"Обидві форми","lead":"Після деяких дієслів можна вживати обидві форми, а значення не змінюється.","tiles":[{"role":"begin · start · continue · intend","label":"to do = doing","tone":"opinion"}],"examples":[{"text":"She began <b>dancing / to dance</b>.","plain":"She began dancing / to dance.","note":"обидві"},{"text":"She is beginning <b>to dance</b>.","plain":"She is beginning to dance.","note":"НЕ beginning dancing"},{"text":"He advised <b>me to stay</b> indoors.","plain":"He advised me to stay indoors.","note":"з додатком — to-inf"},{"text":"He advised <b>staying</b> indoors.","plain":"He advised staying indoors.","note":"без додатка — -ing"},{"text":"We <b>were advised to stay</b> indoors.","plain":"We were advised to stay indoors.","note":"у пасиві — to-inf"}],"note":"Дві -ing форми поспіль англійська уникає: <i>is beginning <b>to dance</b></i>.","tabs":[{"title":"advise, allow…","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\"><b>advise, allow, encourage, permit, require</b>: з додатком — to-inf, без додатка — -ing, у пасиві — to-inf.</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">Employees <b>are required to work</b> on Saturdays.</div>"},{"title":"need + -ing","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\"><b>need, require, want</b> + -ing мають пасивне значення:</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">The trees <b>need pruning</b>. = The trees <b>need to be pruned</b>.</div>"}]}$g79$::jsonb, null, 12
