insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g81$th_15$g81$, $g82$Інфінітив або -ing зі зміною значення$g82$, $g83$advanced$g83$, $g84$cases$g84$, $g85${"step":"To do ≠ doing","kicker":"Від форми залежить зміст","lead":"Найважча група. Загальна логіка: <b>to-inf дивиться вперед</b>, <b>-ing — на вже зроблене або на процес</b>.","cards":[{"icon":"↻","title":"remember / forget","text":"<b>to do</b> — не забути / забути зробити<br><b>doing</b> — пам'ятати / забути, що вже робив.","example":"Remember <b>to feed</b> the dog. / I'll never forget <b>seeing</b> the Eiffel Tower.","examplePlain":"Remember to feed the dog. I'll never forget seeing the Eiffel Tower."},{"icon":"■","title":"stop","text":"<b>to do</b> — зупинитися, щоб<br><b>doing</b> — припинити.","example":"Let's stop <b>to admire</b> the view. / He stopped <b>studying</b>.","examplePlain":"Let's stop to admire the view. He stopped studying."},{"icon":"?","title":"try","text":"<b>to do</b> — намагатися<br><b>doing</b> — спробувати як експеримент.","example":"Try <b>to throw</b> the ball. / Try <b>cooking</b> with olive oil.","examplePlain":"Try to throw the ball. Try cooking with olive oil."},{"icon":"✉","title":"regret","text":"<b>to inform</b> — з жалем повідомляю<br><b>doing</b> — шкодую, що зробив."},{"icon":"→","title":"mean","text":"<b>to do</b> — мати намір<br><b>doing</b> — означати, тягнути за собою.","example":"It means <b>taking</b> the train.","examplePlain":"It means taking the train."},{"icon":"»","title":"go on","text":"<b>to do</b> — перейти до наступного<br><b>doing</b> — продовжувати те саме."},{"icon":"♡","title":"be sorry","text":"<b>to hear</b> — шкода чути<br><b>for yelling</b> — вибачатися за."},{"icon":"✕","title":"hate","text":"<b>to argue</b> — не хочу (зараз)<br><b>bothering</b> — неприємно, що роблю."},{"icon":"!","title":"be afraid","text":"<b>to jump</b> — боятися зробити<br><b>of skidding</b> — боятися, що станеться."},{"icon":"≥","title":"prefer","text":"<b>would prefer to eat</b> — конкретний вибір<br><b>prefer reading</b> — загалом.","example":"prefer <b>to drive</b> rather than <b>take</b> the bus","examplePlain":"prefer to drive rather than take the bus"},{"icon":"+","title":"want","text":"<b>to go</b> — хотіти<br><b>cleaning</b> — потребувати."}]}$g85$::jsonb, null, 13
