insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g87$th_16$g87$, $g88$Дієприкметники: boring чи bored?$g88$, $g89$elementary$g89$, $g90$formula$g90$, $g91${"step":"Boring чи bored","kicker":"Причина чи почуття","lead":"Дієприкметники на <b>-ing</b> описують, <b>який</b> предмет чи людина. На <b>-ed</b> — <b>що відчуває</b> людина.","tiles":[{"role":"причина почуття (річ, ситуація)","label":"-ing","tone":"colour"},{"role":"саме почуття (людина)","label":"-ed","tone":"opinion"}],"examples":[{"text":"It was a <b>surprising</b> decision.","plain":"It was a surprising decision.","note":"яке рішення? — дивне"},{"text":"We were <b>surprised</b> by his story.","plain":"We were surprised by his story.","note":"що відчули? — подив"},{"text":"The film was <b>boring</b>, so I was <b>bored</b>.","plain":"The film was boring, so I was bored.","note":"-ing і -ed поруч"}],"note":"<b>Типова помилка:</b> <s>I am boring</s> (= я нудний), коли хочеш сказати <i>I am bored</i> (= мені нудно).","tabs":[{"title":"Інші пари","html":"<div class=\"overflow-x-auto mb-3\"><table class=\"w-full text-body-sm border-collapse\">\n  <thead><tr><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">-ing (який?)</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">-ed (що відчуває?)</th></tr></thead>\n  <tbody><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">interesting</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">interested</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">exciting</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">excited</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">tiring</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">tired</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">amazing</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">amazed</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">disappointing</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">disappointed</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">terrifying</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">terrified</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">exhausting</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">exhausted</td></tr></tbody>\n</table></div>"}]}$g91$::jsonb, null, 14
