insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g93$th_17$g93$, $g94$Дієприкметникові звороти: Having finished, …$g94$, $g95$advanced$g95$, $g96$formula$g96$, $g97${"step":"Звороти","kicker":"Скорочуємо підрядне речення","lead":"Дієприкметниковий зворот скорочує підрядне речення. Підмет звороту має <b>збігатися</b> з підметом головного речення.","tiles":[{"role":"одночасно","label":"V-ing","tone":"opinion"},{"role":"раніше","label":"Having + V3","tone":"colour"},{"role":"пасив","label":"V3 / Having been + V3","tone":"size"}],"examples":[{"text":"The woman <b>waiting</b> for me is my mum.","plain":"The woman waiting for me is my mum.","note":"замість who"},{"text":"The watch <b>displayed</b> in the window is expensive.","plain":"The watch displayed in the window is expensive.","note":"замість which, пасив"},{"text":"<b>Having put</b> on weight, I decided to go on a diet.","plain":"Having put on weight, I decided to go on a diet.","note":"причина, раніше"},{"text":"<b>After passing</b> his test, he bought a car.","plain":"After passing his test, he bought a car.","note":"час"},{"text":"He was driving, <b>listening</b> to the radio.","plain":"He was driving, listening to the radio.","note":"паралельні дії"}],"note":"<b>Типова помилка:</b> <s>Walking home, the rain started.</s> — підмети різні, і виходить, ніби дощ ішов додому.","tabs":[{"title":"Ще приклади","html":"<div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\"><b>Feeling</b> tired, Laura didn't go. — причина<br>We met John <b>while travelling</b>. — час<br><b>Winning</b> the lottery, she jumped for joy. — послідовні дії</div>"}]}$g97$::jsonb, null, 15
