insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g99$th_18$g99$, $g100$Стоп-калька: неособові форми$g100$, $g101$elementary$g101$, $g102$traps$g102$, $g103${"step":"Стоп-калька","kicker":"Типові помилки","lead":"Три головні кальки: «хочу, щоб ти…» → <i>want you to</i> · «для того щоб» → <i>to</i>, а не <i>for to</i> · <i>to</i> після прийменника-to → <i>-ing</i>.","items":[{"title":"«Я хочу, щоб ти прийшов»","bad":"I want that you come.","good":"I want <b>you to come</b>.","goodPlain":"I want you to come.","rule":"Після want — додаток + to-inf, без that."},{"title":"«Вона змусила мене вибачитися»","bad":"She made me to apologise.","good":"She made me <b>apologise</b>.","goodPlain":"She made me apologise.","rule":"Після make + додаток — без to. Але в пасиві: <i>I was made to apologise.</i>"},{"title":"«Я бачив, як він пішов»","bad":"I saw him to leave.","good":"I saw him <b>leave</b>.","goodPlain":"I saw him leave.","rule":"Після see + додаток — без to."},{"title":"«Чекаю на відповідь»","bad":"I look forward to hear from you.","good":"I look forward to <b>hearing</b> from you.","goodPlain":"I look forward to hearing from you.","rule":"У <i>look forward to</i> to — прийменник, тому далі -ing."},{"title":"«Пропоную піти»","bad":"I suggest to go.","good":"I suggest <b>going</b>.","goodPlain":"I suggest going.","rule":"Після suggest — тільки -ing."},{"title":"«Варто відвідати»","bad":"It's worth to visit.","good":"It's worth <b>visiting</b>.","goodPlain":"It's worth visiting.","rule":"Після worth — тільки -ing."},{"title":"«Я прийшов, щоб допомогти»","bad":"I came for to help.","good":"I came <b>to help</b>.","goodPlain":"I came to help.","rule":"Мета — просто to-inf, без for."},{"title":"«Він достатньо сильний»","bad":"He is enough strong.","good":"He is <b>strong enough</b>.","goodPlain":"He is strong enough.","rule":"enough стоїть ПІСЛЯ прикметника."},{"title":"«Фільм був дуже нудний»","bad":"The film was very bored.","good":"The film was very <b>boring</b>.","goodPlain":"The film was very boring.","rule":"Фільм — причина нудьги, тому -ing."}]}$g103$::jsonb, null, 16
