insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g105$th_5$g105$, $g106$Інфінітив як означення: the first to do, something to do$g106$, $g107$advanced$g107$, $g108$prose$g108$, null, $g109$
        <p class="text-slate-600 mb-3">Інфінітив після іменника чи займенника описує його — часто з відтінком «який треба / можна зробити». Українською перекладаємо підрядним реченням.</p>
        <div class="bg-indigo-50 border border-indigo-100 p-3 rounded-lg text-sm mb-3">
          <strong>Формули:</strong> the first / the last / the only / the second + to-inf · something / nobody / nothing + to-inf · the man / the time + to-inf
        </div>
        <ul class="text-xs space-y-1 text-slate-700">
          <li>• <em>She was <strong>the first to see</strong> the danger.</em> — першою, хто побачив</li>
          <li>• <em>Have you <strong>anything</strong> else <strong>to say</strong>? / There was <strong>nobody to show</strong> him the way.</em></li>
          <li>• <em>He is just <strong>the man to do</strong> it. / It is not <strong>the right time to discuss</strong> this.</em></li>
          <li>• Пасивний інфінітив, коли дію виконують над іменником: <em>the plan <strong>to be discussed</strong>, a chance <strong>not to be missed</strong>, the letters <strong>to be answered</strong></em></li>
          <li>• Прийменник лишається в кінці: <em>a family <strong>to take care of</strong>, nothing <strong>to worry about</strong>, the man <strong>to speak to</strong></em></li>
          <li>• Сталі вирази: <em>There is nothing <strong>to be done</strong>. / Who <strong>is to blame</strong>? / The house <strong>is to let</strong>. / Be <strong>sure to come</strong>.</em></li>
        </ul>
      $g109$, 17
from public.topics where slug = $g110$verbals$g110$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g111$th_7$g111$, $g112$Прикметник + інфінітив: hard to please, nice to work with$g112$, $g113$advanced$g113$, $g114$prose$g114$, null, $g115$
        <p class="text-slate-600 mb-3">Після прикметників <em>easy, hard, difficult, impossible, nice, pleasant, dangerous</em> підмет речення — це <strong>об'єкт</strong> дії інфінітива. Українською так не кажемо, тому конструкція незвична.</p>
        <div class="bg-indigo-50 border border-indigo-100 p-3 rounded-lg text-sm mb-3">
          <strong>Формула:</strong> Subject + be + adjective + to-inf (+ прийменник)
        </div>
        <ul class="text-xs space-y-1 text-slate-700">
          <li>• <em>He is <strong>hard to please</strong>.</em> — Йому важко догодити.</li>
          <li>• <em>She is <strong>nice to work with</strong>.</em> — З нею приємно працювати.</li>
          <li>• <em>His story was <strong>hard to prove</strong>.</em> — Його історію важко було довести.</li>
          <li>• <em>She is <strong>pleasant to look at</strong>.</em> — На неї приємно дивитися.</li>
          <li>• Додаток НЕ повторюємо: <s>He is hard to please him.</s></li>
          <li>• <strong>Вставні звороти</strong> з інфінітивом: <em>to tell the truth, to begin with, to put it mildly, to say the least, to cut a long story short, to crown it all</em> — <em><strong>To put it mildly</strong>, he was not very clever.</em></li>
        </ul>
      $g115$, 18
from public.topics where slug = $g116$verbals$g116$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position;

