  ($g2941$verb_abcd_12$g2941$, $g2942$abcd$g2942$, $g2943$intermediate$g2943$, $g2944${"id":"verb_abcd_12","level":"intermediate","q":"12. 'The printer ink needs ______. Do you know how to do it?'","options":["A) replacing","B) to replace","C) being replaced","D) you replace it"],"correct":0,"explanation":"Need + -ing = пасивне значення."}$g2944$, 11),
  ($g2945$verb_abcd_13$g2945$, $g2946$abcd$g2946$, $g2947$intermediate$g2947$, $g2948${"id":"verb_abcd_13","level":"intermediate","q":"13. 'Bethany looked a bit upset. Is she OK?' 'No, she isn't. I ______ crying her eyes out in the girls' toilets.'","options":["A) found she","B) found her","C) found","D) found her to be"],"correct":1,"explanation":"Find + додаток + -ing."}$g2948$, 12),
  ($g2949$verb_abcd_14$g2949$, $g2950$abcd$g2950$, $g2951$intermediate$g2951$, $g2952${"id":"verb_abcd_14","level":"intermediate","q":"14. The coach urged ______ a special effort during the second half of the match.","options":["A) to make his players","B) making his players","C) his players making","D) his players to make"],"correct":3,"explanation":"Urge + додаток + to-inf."}$g2952$, 13),
  ($g2953$verb_abcd_15$g2953$, $g2954$abcd$g2954$, $g2955$elementary$g2955$, $g2956${"id":"verb_abcd_15","level":"elementary","q":"15. 'Do you think your boss will let you ______ some time off next week?'","options":["A) taking","B) to take","C) take","D) to taking"],"correct":2,"explanation":"Let + додаток + інфінітив без to."}$g2956$, 14),
  ($g2957$verb_abcd_16$g2957$, $g2958$abcd$g2958$, $g2959$intermediate$g2959$, $g2960${"id":"verb_abcd_16","level":"intermediate","q":"16. It's no use ______ with her – she won't listen.","options":["A) arguing","B) to argue","C) that you argue","D) to be arguing"],"correct":0,"explanation":"It's no use + -ing."}$g2960$, 15),
  ($g2961$verb_abcd_17$g2961$, $g2962$abcd$g2962$, $g2963$advanced$g2963$, $g2964${"id":"verb_abcd_17","level":"advanced","q":"17. We regret ______ passengers that all flights have been cancelled due to bad weather.","options":["A) informing","B) having informed","C) to inform","D) to informing"],"correct":2,"explanation":"Regret to inform — з жалем повідомляємо."}$g2964$, 16),
  ($g2965$verb_abcd_18$g2965$, $g2966$abcd$g2966$, $g2967$advanced$g2967$, $g2968${"id":"verb_abcd_18","level":"advanced","q":"18. Matthew's determination ______ against all the odds is an inspiration to us all.","options":["A) to succeed","B) succeeding","C) to be succeed","D) his succeeding"],"correct":0,"explanation":"Determination + to-inf (означення)."}$g2968$, 17),
  ($g2969$verb_abcd_19$g2969$, $g2970$abcd$g2970$, $g2971$intermediate$g2971$, $g2972${"id":"verb_abcd_19","level":"intermediate","q":"19. Danielle was relieved ______ that she had passed her exams with flying colours!","options":["A) finding out","B) to find out","C) to finding out","D) find out"],"correct":1,"explanation":"Прикметник почуття + to-inf."}$g2972$, 18),
  ($g2973$verb_abcd_20$g2973$, $g2974$abcd$g2974$, $g2975$advanced$g2975$, $g2976${"id":"verb_abcd_20","level":"advanced","q":"20. Any leftover plastic cups, plates and bowls ______ to the store cupboard.","options":["A) are to be returned","B) to return","C) are to return","D) must be returning"],"correct":0,"explanation":"Be to + пасивний інфінітив — офіційна інструкція."}$g2976$, 19)
) as v(lid, type, level, payload, pos)
on conflict (legacy_id) where student_id is null do update set
  topic_id = excluded.topic_id, type = excluded.type, level = excluded.level,
  payload = excluded.payload, position = excluded.position;

commit;

-- Контроль: блоки теорії за рівнями та кількість вправ за типами
select 'теорія' as що, tb.level as деталь, count(*) from public.theory_blocks tb join public.topics t on t.id = tb.topic_id
  where t.slug = $g2989$verbals$g2989$ group by tb.level
union all
select 'вправи', e.type, count(*) from public.exercises e join public.topics t on t.id = e.topic_id
  where t.slug = $g2990$verbals$g2990$ and e.student_id is null group by e.type order by 1, 2;
